import{_ as e,o as a,c as r,a0 as n}from"./chunks/framework.D7EjqxMK.js";const p=JSON.parse('{"title":"Agent 安全与评估最新进展","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/05_前沿趋势/08_Agent安全与评估最新进展.md","filePath":"06-agent/05_前沿趋势/08_Agent安全与评估最新进展.md"}'),o={name:"06-agent/05_前沿趋势/08_Agent安全与评估最新进展.md"};function i(d,t,l,g,h,s){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="agent-安全与评估最新进展" tabindex="-1">Agent 安全与评估最新进展 <a class="header-anchor" href="#agent-安全与评估最新进展" aria-label="Permalink to &quot;Agent 安全与评估最新进展&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块五 · 05_前沿趋势 · 第 8 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：Agent 安全基础</p></blockquote><hr><h2 id="_1-owasp-agentic-ai-top-10-已验证来源" tabindex="-1">1. OWASP Agentic AI Top 10（已验证来源） <a class="header-anchor" href="#_1-owasp-agentic-ai-top-10-已验证来源" aria-label="Permalink to &quot;1. OWASP Agentic AI Top 10（已验证来源）&quot;">​</a></h2><p><strong>来源</strong>：<a href="https://genai.owasp.org/2025/12/09/owasp-top-10-for-agentic-applications-the-benchmark-for-agentic-security-in-the-age-of-autonomous-ai/" target="_blank" rel="noreferrer">OWASP Top 10 for Agentic Applications</a> <a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">来源: OWASP 报告 v1.1 Dec 2025</a></p><h3 id="十大风险" tabindex="-1">十大风险 <a class="header-anchor" href="#十大风险" aria-label="Permalink to &quot;十大风险&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>风险</th><th>描述</th><th>严重度</th></tr></thead><tbody><tr><td>A01</td><td>工具滥用</td><td>Agent 调用未授权工具</td><td>🔴</td></tr><tr><td>A02</td><td>提示注入</td><td>恶意输入诱导 Agent</td><td>🔴</td></tr><tr><td>A03</td><td>越狱攻击</td><td>绕过安全限制</td><td>🔴</td></tr><tr><td>A04</td><td>数据泄露</td><td>暴露敏感数据</td><td>🟠</td></tr><tr><td>A05</td><td>幻觉执行</td><td>基于错误信息执行</td><td>🟠</td></tr><tr><td>A06</td><td>权限逃逸</td><td>超出设计权限</td><td>🟠</td></tr><tr><td>A07</td><td>无限循环/资源耗尽</td><td>Agent 陷入死循环</td><td>🟡</td></tr><tr><td>A08</td><td>供应链攻击</td><td>通过工具注入恶意代码</td><td>🟠</td></tr><tr><td>A09</td><td>审计缺失</td><td>Agent 行为不可追溯</td><td>🟡</td></tr><tr><td>A10</td><td>伦理与偏见</td><td>歧视性决策</td><td>🟡</td></tr></tbody></table><hr><h2 id="_2-agentharm-已验证来源-iclr-2025" tabindex="-1">2. AgentHarm（已验证来源 - ICLR 2025） <a class="header-anchor" href="#_2-agentharm-已验证来源-iclr-2025" aria-label="Permalink to &quot;2. AgentHarm（已验证来源 - ICLR 2025）&quot;">​</a></h2><p><strong>来源</strong>：<a href="https://proceedings.iclr.cc/paper_files/paper/2025/file/c493d23af93118975cdbc32cbe7323f5-Paper-Conference.pdf" target="_blank" rel="noreferrer">AgentHarm (ICLR 2025)</a></p><p>AgentHarm 是衡量 LLM Agent 有害性的基准，由 UC Berkeley、Columbia 等机构提出，发表于 ICLR 2025。</p><hr><h2 id="_3-openagentsafety-已验证来源-iclr-2026" tabindex="-1">3. OpenAgentSafety（已验证来源 - ICLR 2026） <a class="header-anchor" href="#_3-openagentsafety-已验证来源-iclr-2026" aria-label="Permalink to &quot;3. OpenAgentSafety（已验证来源 - ICLR 2026）&quot;">​</a></h2><p><strong>来源</strong>：<a href="https://openreview.net/pdf?id=xggSxCFQbA" target="_blank" rel="noreferrer">OpenAgentSafety (ICLR 2026)</a></p><p>由 Carnegie Mellon University、Meta AI、Carnegie Mellon 等机构联合提出。OpenAgentSafety 是一个全面评估真实世界 AI Agent 安全性的框架。</p><hr><h2 id="_4-agentthreatbench" tabindex="-1">4. AgentThreatBench <a class="header-anchor" href="#_4-agentthreatbench" aria-label="Permalink to &quot;4. AgentThreatBench&quot;">​</a></h2><p><strong>来源</strong>：<a href="https://github.com/UKGovernmentBEIS/inspect_evals/issues/1031" target="_blank" rel="noreferrer">AgentThreatBench (GitHub)</a></p><p>UK Government BEIS 的 AgentThreatBench，基于 OWASP Top 10 for Agentic Applications 实现。</p><hr><h2 id="_5-owasp-报告下载" tabindex="-1">5. OWASP 报告下载 <a class="header-anchor" href="#_5-owasp-报告下载" aria-label="Permalink to &quot;5. OWASP 报告下载&quot;">​</a></h2><ul><li><a href="https://genai.owasp.org/download/50592/" target="_blank" rel="noreferrer">State of Agentic AI Security and Governance (OWASP, July 2025)</a></li><li><a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">Agentic AI Threats and Mitigations (OWASP v1.1, Dec 2025)</a></li></ul><hr><h2 id="_6-参考资料" tabindex="-1">6. 参考资料 <a class="header-anchor" href="#_6-参考资料" aria-label="Permalink to &quot;6. 参考资料&quot;">​</a></h2><ul><li><a href="https://genai.owasp.org/2025/12/09/owasp-top-10-for-agentic-applications-the-benchmark-for-agentic-security-in-the-age-of-autonomous-ai/" target="_blank" rel="noreferrer">OWASP Top 10 for Agentic Applications</a></li><li><a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">OWASP Agentic AI 报告 v1.1 (Dec 2025)</a></li><li><a href="https://genai.owasp.org/download/50592/" target="_blank" rel="noreferrer">State of Agentic AI Security and Governance (OWASP, July 2025)</a></li><li><a href="https://proceedings.iclr.cc/paper_files/paper/2025/file/c493d23af93118975cdbc32cbe7323f5-Paper-Conference.pdf" target="_blank" rel="noreferrer">AgentHarm (ICLR 2025)</a></li><li><a href="https://openreview.net/pdf?id=xggSxCFQbA" target="_blank" rel="noreferrer">OpenAgentSafety (ICLR 2026)</a></li><li><a href="https://github.com/UKGovernmentBEIS/inspect_evals/issues/1031" target="_blank" rel="noreferrer">AgentThreatBench (GitHub)</a></li><li><a href="https://huggingface.co/blog/royswastik/evaluating-agentic-ai-part-4-security" target="_blank" rel="noreferrer">Part 4: Security Evaluation of Agentic AI Systems (Hugging Face)</a></li></ul>',25)])])}const f=e(o,[["render",i]]);export{p as __pageData,f as default};
